diff --git a/cmd/entire/cli/integration_test/global_enable_test.go b/cmd/entire/cli/integration_test/global_enable_test.go
new file mode 100644
index 00000000..0f3ef60a
--- /dev/null
+++ b/cmd/entire/cli/integration_test/global_enable_test.go
@@ -0,0 +1,267 @@
+//go:build integration
+
+package integration
+
+import (
+	"context"
+	"encoding/json"
+	"os"
+	"os/exec"
+	"path/filepath"
+	"strings"
+	"testing"
+
+	"github.com/entireio/cli/cmd/entire/cli/paths"
+	"github.com/entireio/cli/cmd/entire/cli/strategy"
+	"github.com/entireio/cli/cmd/entire/cli/testutil"
+	"github.com/entireio/cli/cmd/entire/cli/trailers"
+)
+
+// newGloballyTrackedEnv creates a repo with a commit on a feature branch and
+// NO repo-level Entire setup (no InitEntire, no .entire anywhere), plus a
+// per-test ENTIRE_CONFIG_DIR. When globalEnabled is true, that config dir
+// contains a user-global settings file enabling the global tier.
+//
+// The config dir override rides on env.ExtraEnv (cliEnv/gitHookEnv append it
+// after the TestMain-wide ENTIRE_CONFIG_DIR; last duplicate wins in exec.Cmd)
+// and is returned for hook invocations that need it passed explicitly.
+func newGloballyTrackedEnv(t *testing.T, globalEnabled bool) (*TestEnv, []string) {
+	t.Helper()
+	env := NewTestEnv(t)
+	env.InitRepo()
+	env.WriteFile("README.md", "# Global tracking test")
+	env.GitAdd("README.md")
+	env.GitCommit("Initial commit")
+	env.GitCheckoutNewBranch("feature/global")
+
+	configDir := t.TempDir()
+	if globalEnabled {
+		if err := os.WriteFile(filepath.Join(configDir, "settings.json"),
+			[]byte(`{"global":{"enabled":true}}`), 0o600); err != nil {
+			t.Fatalf("write user-global settings: %v", err)
+		}
+	}
+	extraEnv := []string{"ENTIRE_CONFIG_DIR=" + configDir}
+	env.ExtraEnv = append(env.ExtraEnv, extraEnv...)
+	return env, extraEnv
+}
+
+// gitStatusPorcelain runs `git status --porcelain` in the repo and returns
+// the trimmed output. Empty output is the invisible-mode product guarantee:
+// global tracking must never surface anything in the user's git status.
+func gitStatusPorcelain(t *testing.T, env *TestEnv) string {
+	t.Helper()
+	cmd := exec.CommandContext(context.Background(), "git", "status", "--porcelain")
+	cmd.Dir = env.RepoDir
+	cmd.Env = testutil.GitIsolatedEnv()
+	out, err := cmd.CombinedOutput()
+	if err != nil {
+		t.Fatalf("git status --porcelain: %v\n%s", err, out)
+	}
+	return strings.TrimSpace(string(out))
+}
+
+func runClaudeHook(t *testing.T, env *TestEnv, extraEnv []string, hookName string, input map[string]string) {
+	t.Helper()
+	inputJSON, err := json.Marshal(input)
+	if err != nil {
+		t.Fatalf("marshal hook input: %v", err)
+	}
+	runner := NewHookRunner(env.RepoDir, env.ClaudeProjectDir, t)
+	if err := runner.runHookInRepoDirWithExtraEnv(hookName, inputJSON, extraEnv); err != nil {
+		t.Fatalf("hook %s: %v", hookName, err)
+	}
+}
+
+func assertNoWorktreeEntireDir(t *testing.T, env *TestEnv) {
+	t.Helper()
+	if _, err := os.Lstat(filepath.Join(env.RepoDir, ".entire")); !os.IsNotExist(err) {
+		t.Errorf(".entire exists in the worktree of a globally tracked repo (err=%v)", err)
+	}
+}
+
+// TestGlobalEnable_LazyInvisibleSetup exercises the full lazy invisible
+// enable in a repo with no repo-level setup and the user-global tier on:
+// the first hook event installs git hooks and marks the clone, every runtime
+// write lands under .git/entire/worktree/, and git status stays clean.
+func TestGlobalEnable_LazyInvisibleSetup(t *testing.T) {
+	t.Parallel()
+	env, extraEnv := newGloballyTrackedEnv(t, true)
+	ctx := context.Background()
+
+	sessionID := "global-test-session-1"
+	runClaudeHook(t, env, extraEnv, "user-prompt-submit", map[string]string{
+		"session_id":      sessionID,
+		"transcript_path": "",
+		"prompt":          "Create hello file",
+	})
+
+	// Lazy enable happened, entirely inside .git/.
+	if !strategy.IsGitHookInstalledInDir(ctx, env.RepoDir) {
+		t.Error("git hooks not installed after first hook event")
+	}
+	prefsData, err := os.ReadFile(filepath.Join(env.RepoDir, ".git", "entire", "preferences.json"))
+	if err != nil {
+		t.Fatalf("clone preferences not written: %v", err)
+	}
+	var prefs struct {
+		GlobalSetupCompleted bool `json:"global_setup_completed"`
+	}
+	if err := json.Unmarshal(prefsData, &prefs); err != nil {
+		t.Fatalf("parse clone preferences: %v", err)
+	}
+	if !prefs.GlobalSetupCompleted {
+		t.Errorf("clone preferences not marked global_setup_completed: %s", prefsData)
+	}
+	if !env.BranchExists("entire/checkpoints/v1") {
+		t.Error("checkpoint metadata ref not created by lazy enable")
+	}
+
+	// The invisible guarantee: no worktree files, empty git status. The
+	// routed base is namespaced per worktree; env.RepoDir is a main
+	// worktree, whose key hashes the empty worktree ID.

+// WorktreeIDHashLength is the number of hex characters HashWorktreeID
+// returns. checkpoint.WorktreeIDHashLength aliases it for package locality;
+// that mirror currently has no consumers of its own — nothing parses shadow
+// branch names by hash length.
+const WorktreeIDHashLength = 6
+
+// HashWorktreeID returns a short stable hash of a worktree identifier (a
+// GetWorktreeID result; "" for the main worktree). It is the per-worktree
+// namespace key used both in shadow branch names
+// ("entire/<commit>-<worktreeHash>", via checkpoint.HashWorktreeID, which
+// delegates here) and in the invisible-routing runtime directory layout
+// (<git-common-dir>/entire/worktree/<worktreeHash>/...).
+func HashWorktreeID(worktreeID string) string {
+	h := sha256.Sum256([]byte(worktreeID))
+	return hex.EncodeToString(h[:])[:WorktreeIDHashLength]
+}
+
 // GetWorktreeID returns the internal git worktree identifier for the given path.
-// For the main worktree (where .git is a directory), returns empty string.
+// For the main worktree, returns empty string — whether .git is a directory or
+// a `git init/clone --separate-git-dir` .git file pointing at a full git dir.
 // For linked worktrees (where .git is a file), extracts the name from
 // .git/worktrees/<name>/ path. This name is stable across `git worktree move`.
 func GetWorktreeID(worktreePath string) (string, error) {
@@ -40,9 +60,76 @@ func GetWorktreeID(worktreePath string) (string, error) {
 		return worktreeID, nil
 	}

+	// A .git file whose gitdir matches no known linked-worktree layout is not
+	// automatically an error: `git init/clone --separate-git-dir` produces
+	// exactly this shape for a MAIN worktree (a .git file pointing at a full
+	// git dir at an arbitrary path), whose worktree ID is "". Distinguish on
+	// disk rather than lexically: a linked-worktree admin dir
+	// (<commondir>/worktrees/<id>) always contains a `commondir` file, a full
+	// git dir never does.
+	resolved := resolveGitdirPath(worktreePath, gitdir)
+	if isMainWorktreeGitDir(resolved) {
+		return "", nil
+	}
+
+	// A LINKED worktree of a separate-git-dir repo also matches no lexical
+	// marker (its admin dir is <sepdir>/worktrees/<id>, and <sepdir> is not
+	// named .git or .bare). When the resolved dir is a worktree admin dir
+	// (has a commondir file), the ID is whatever follows the last
+	// /worktrees/ segment — git always places admin dirs there.
+	if isLinkedWorktreeAdminDir(resolved) {
+		normalized := strings.TrimSuffix(strings.ReplaceAll(gitdir, "\\", "/"), "/")
+		if idx := strings.LastIndex(normalized, "/worktrees/"); idx >= 0 {
+			return normalized[idx+len("/worktrees/"):], nil
+		}
+	}
+
 	return "", fmt.Errorf("unexpected gitdir format (no worktrees): %s", gitdir)
 }

+// resolveGitdirPath resolves a .git-file gitdir value (which may be relative
+// to the worktree root) to a filesystem path suitable for probing.
+func resolveGitdirPath(worktreePath, gitdir string) string {
+	gitdir = filepath.FromSlash(strings.ReplaceAll(gitdir, "\\", "/"))
+	if !filepath.IsAbs(gitdir) {
+		gitdir = filepath.Join(worktreePath, gitdir)
+	}
+	return filepath.Clean(gitdir)
+}
+
+// isMainWorktreeGitDir reports whether path is a full (main-worktree) git
+// directory, as opposed to a linked-worktree admin dir. Both contain HEAD;
+// only linked-worktree admin dirs contain a `commondir` file pointing back at
+// the shared git dir. A path that is missing or has no HEAD is neither.
+func isMainWorktreeGitDir(path string) bool {
+	info, err := os.Stat(path) //nolint:gosec // path comes from the repo's own .git file; read-only probe
+	if err != nil || !info.IsDir() {
+		return false
+	}
+	if _, err := os.Stat(filepath.Join(path, "HEAD")); err != nil { //nolint:gosec // read-only probe of the repo's own gitdir
+		return false
+	}
+	if _, err := os.Stat(filepath.Join(path, "commondir")); err == nil { //nolint:gosec // read-only probe of the repo's own gitdir
+		return false // linked-worktree admin dir with an unrecognized layout
+	}
+	return true
+}
+
+// isLinkedWorktreeAdminDir reports whether path is a linked-worktree admin
+// dir (<commondir>/worktrees/<id>): a directory with both HEAD and the
+// commondir file pointing back at the shared git dir.
+func isLinkedWorktreeAdminDir(path string) bool {
+	info, err := os.Stat(path) //nolint:gosec // path comes from the repo's own .git file; read-only probe
+	if err != nil || !info.IsDir() {
+		return false
+	}
+	if _, err := os.Stat(filepath.Join(path, "HEAD")); err != nil { //nolint:gosec // read-only probe of the repo's own gitdir
+		return false
+	}
+	_, err = os.Stat(filepath.Join(path, "commondir")) //nolint:gosec // read-only probe of the repo's own gitdir
+	return err == nil
+}
+
 func parseWorktreeID(gitdir string) (string, bool) {
 	gitdir = strings.TrimSuffix(strings.ReplaceAll(gitdir, "\\", "/"), "/")

