// Directory constants
const (
	EntireDir         = ".entire"
	EntireTmpDir      = ".entire/tmp"
	EntireMetadataDir = ".entire/metadata"
	EntireLogsDir     = ".entire/logs"

	osWindows = "windows"
	osDarwin  = "darwin"
)

// Metadata file names
